const pixTlv=(id,value)=>{value=String(value);return id+String(value.length).padStart(2,'0')+value};
function pixCrc16(value){let crc=0xFFFF;for(const byte of new TextEncoder().encode(value)){crc^=byte<<8;for(let bit=0;bit<8;bit++)crc=crc&0x8000?((crc<<1)^0x1021)&0xFFFF:(crc<<1)&0xFFFF}return crc.toString(16).toUpperCase().padStart(4,'0')}
function cleanPixText(value,max){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim().slice(0,max)}
function createPixPayload(settings,order,amount){let key=String(settings.pixKey||'').trim(),merchant=cleanPixText(settings.company,25)||'PROTECEXTINTORES',city=cleanPixText(settings.pixCity,15),amountNumber=Number(amount),amountText=amountNumber.toFixed(2),txid=String(order.code||'PEDIDO').replace(/[^A-Za-z0-9]/g,'').slice(0,25)||'***';if(!key)throw Error('Cadastre a chave Pix em Configurações.');if(!city)throw Error('Informe uma cidade válida em Configurações > Pagamento via Pix.');if(!Number.isFinite(amountNumber)||amountNumber<=0)throw Error('Informe um valor válido para o Pix.');let account=pixTlv('00','br.gov.bcb.pix')+pixTlv('01',key);if(account.length>99)throw Error('A chave Pix é longa demais para gerar o QR Code estático.');let payload='000201'+pixTlv('26',account)+'52040000'+'5303986'+pixTlv('54',amountText)+'5802BR'+pixTlv('59',merchant)+pixTlv('60',city)+pixTlv('62',pixTlv('05',txid))+'6304';return payload+pixCrc16(payload)}
function pixQrDataUrl(payload){let qr=createQRCode(payload,{errorCorrectionLevel:'M'}),size=qr.modules.size,border=4,parts=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(qr.modules.get(y,x))parts.push(`M${x+border} ${y+border}h1v1h-1z`);let dimension=size+border*2,svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${dimension} ${dimension}" shape-rendering="crispEdges"><path fill="#fff" d="M0 0h${dimension}v${dimension}H0z"/><path fill="#000" d="${parts.join('')}"/></svg>`;return 'data:image/svg+xml;base64,'+btoa(svg)}
function pixHexBytes(value){if(!/^[a-f0-9]{64}$/i.test(String(value||'')))throw Error('Configure uma chave PIX_CONFIG_ENCRYPTION_KEY com 64 caracteres hexadecimais nos secrets do Worker.');return Uint8Array.from(String(value).match(/.{2}/g),part=>parseInt(part,16))}
async function pixEncryptionKey(env){return crypto.subtle.importKey('raw',pixHexBytes(env.PIX_CONFIG_ENCRYPTION_KEY),'AES-GCM',false,['encrypt','decrypt'])}
async function pixEncryptConfig(env,config){let iv=crypto.getRandomValues(new Uint8Array(12)),key=await pixEncryptionKey(env),data=new TextEncoder().encode(JSON.stringify(config)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,data);return{iv:btoa(String.fromCharCode(...iv)),cipher:btoa(String.fromCharCode(...new Uint8Array(cipher)))}}
async function pixDecryptConfig(env,row){let iv=Uint8Array.from(atob(row.config_iv),char=>char.charCodeAt(0)),cipher=Uint8Array.from(atob(row.config_cipher),char=>char.charCodeAt(0)),key=await pixEncryptionKey(env),clear=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher);return JSON.parse(new TextDecoder().decode(clear))}
async function loadPixProviderConfig(env){try{let row=await env.DB.prepare('SELECT config_cipher,config_iv FROM pix_provider_config WHERE id=1').first();return row?await pixDecryptConfig(env,row):null}catch(error){if(/no such table/i.test(error.message||''))return null;throw error}}
async function storePixProviderConfig(env,config){let encrypted=await pixEncryptConfig(env,config);try{await env.DB.prepare('INSERT INTO pix_provider_config(id,config_cipher,config_iv,updated_at) VALUES(1,?,?,?) ON CONFLICT(id) DO UPDATE SET config_cipher=excluded.config_cipher,config_iv=excluded.config_iv,updated_at=excluded.updated_at').bind(encrypted.cipher,encrypted.iv,now()).run()}catch(error){if(/no such table/i.test(error.message||''))throw Error('Aplique primeiro a migração 0004_pix_provider.sql no banco D1.');throw error}}
