function pixHttpsUrl(value,label){let url;try{url=new URL(String(value||''))}catch{throw Error(`${label} inválido.`)}let host=url.hostname.toLowerCase();if(url.protocol!=='https:'||url.username||url.password||url.hash||url.search||['localhost','127.0.0.1','::1'].includes(host)||host.endsWith('.local')||host.endsWith('.internal')||/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)||host.startsWith('['))throw Error(`${label} precisa ser uma URL HTTPS pública com nome de domínio.`);return url.toString().replace(/\/$/,'')}
