async function pixAccessToken(env,config){let basic=btoa(`${config.clientId}:${config.clientSecret}`),response=await pixFetch(env,config,config.tokenUrl,{method:'POST',headers:{Authorization:'Basic '+basic,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'client_credentials',scope:config.scope||'cob.write cob.read pix.read webhook.write'}).toString()});let data=await response.json().catch(()=>({}));if(!response.ok||!data.access_token)throw Error('O provedor recusou a autenticação. Confira URL, Client ID, Client Secret, escopos e certificado mTLS.');return data.access_token}
async function pixApiRequest(env,config,token,path,method='GET',body=null){let url=config.apiBaseUrl.replace(/\/$/,'')+'/'+String(path).replace(/^\//,'');let response=await pixFetch(env,config,url,{method,headers:{Authorization:'Bearer '+token,Accept:'application/json',...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});let text=await response.text(),data={};try{data=JSON.parse(text)}catch{}if(!response.ok)throw Error(data.mensagem||data.message||`A API Pix respondeu HTTP ${response.status}. Confira a URL base, o escopo e a documentação do banco.`);return data}
