function ensureState(s){const normalizeEntityIds=rows=>{const seen=new Set();for(const row of rows||[]){let entityId=String(row.id||'').trim();if(!entityId||seen.has(entityId)){entityId=crypto.randomUUID();while(seen.has(entityId))entityId=crypto.randomUUID();row.id=entityId}seen.add(entityId)}};s.settings||={};if(!s.settings.company||s.settings.company==='ProtecExtintores')s.settings.company='ProtecExtintores';s.settings.partPrices||={};for(const [name,price] of Object.entries(DEFAULT_PART_PRICES))if(s.settings.partPrices[name]==null)s.settings.partPrices[name]=price;s.types||=[];for(const t of defaultTypes()){let old=s.types.find(x=>x.name===t.name&&String(x.kg||'')===String(t.kg||''));if(!old)s.types.push(t);else if(!(Number(old.price)>0))old.price=t.price}if(!s.types.some(t=>t.name==='Água pressurizada'))s.types.unshift(defaultTypes()[0]);s.products||=[];for(const p of defaultSafetyProducts())if(!s.products.some(x=>x.id===p.id))s.products.push(p);for(const product of s.products){product.category||=(product.type&&/p[óo] qu[ií]mico|co.?2|á?gua pressurizada|dióxido/i.test(product.type)?'Extintores':'Acessórios de prevenção');product.quoteOnly=Boolean(product.quoteOnly||Number(product.price)<=0)}for(const p of defaultProducts()){let old=s.products.find(x=>String(x.kg||'')===String(p.kg||'')&&(x.type===p.type||(p.type==='CO₂'&&/co.?2|dióxido/i.test(x.type||''))));if(!old)s.products.push(p);else if(!(Number(old.price)>0))old.price=p.price}for(const product of s.products)product.category||=(product.type&&/p[óo] qu[ií]mico|co.?2|á?gua pressurizada|dióxido/i.test(product.type)?'Extintores':'Acessórios de prevenção');for(const p of s.products){if(p.id==='p1'&&Number(p.price)===249.9)p.price=225;if(p.id==='p2'&&Number(p.price)===389)p.price=699}const inv=[...defaultProducts().map(p=>({id:`stock-${p.id}`,name:p.name,category:'Extintores',qty:0,unit:'un',minQty:0,unitCost:0})),...Object.entries(DEFAULT_PART_PRICES).filter(([n])=>n!=='Outro').map(([name,unitCost])=>({id:`stock-part-${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,name,category:name==='Mangueira'?'Mangueiras':'Peças',qty:0,unit:'un',minQty:0,unitCost}))];s.inventory||=[];for(const item of inv)if(!s.inventory.some(x=>x.id===item.id))s.inventory.push(item);s.orders||=[];for(const order of s.orders){if(String(order.fulfillmentMethod||'').toLowerCase()==='delivery')order.fulfillmentMethod='delivery';else if(String(order.fulfillmentMethod||'').toLowerCase()==='retirada')order.fulfillmentMethod='retirada';else if(order.deliveryAddress||order.addressId)order.fulfillmentMethod='delivery';else if(order.pickupAddress)order.fulfillmentMethod='retirada'}s.cart||=[];s.employees||=[];s.clients||=[];s.sellers||=[];s.extinguishers||=[];s.services||=[];normalizeEntityIds(s.services);normalizeEntityIds(s.orders);normalizeEntityIds(s.products);normalizeEntityIds(s.clients);normalizeEntityIds(s.employees);normalizeEntityIds(s.sellers);const phoneKey=value=>String(value||'').replace(/\D/g,'');const directoryClient=(name,phone,email,accountId,preferredId)=>{let mail=String(email||'').trim().toLowerCase(),digits=phoneKey(phone),found=(s.clients||[]).find(client=>preferredId&&client.id===preferredId||accountId&&(client.accountId===accountId||client.id===accountId)||mail&&String(client.email||'').trim().toLowerCase()===mail||digits&&phoneKey(client.phone)===digits);if(!found){let clientId=preferredId||accountId||crypto.randomUUID();if(s.clients.some(client=>client.id===clientId))clientId=crypto.randomUUID();found={id:clientId,name:String(name||'Cliente').trim(),phone:String(phone||''),email:String(email||'')};s.clients.push(found)}if(accountId)found.accountId=accountId;if(name&&!found.name)found.name=String(name).trim();if(phone&&!found.phone)found.phone=String(phone);if(email&&!found.email)found.email=String(email);return found};for(const order of s.orders){const client=directoryClient(order.name,order.phone,order.email,order.customerId,order.customerId);order.customerId=order.customerId||client.id}for(const service of s.services){const order=s.orders.find(item=>item.code&&item.code===service.code),client=directoryClient(service.clientName||order?.name,service.clientPhone||order?.phone,service.clientEmail||order?.email,service.customerId||order?.customerId,service.clientId);service.clientId=service.clientId||client.id;if(!service.customerId&&order?.customerId)service.customerId=order.customerId}return s}
