async function employeeMediaUpload(request,env,session,url){
if(!env.MEDIA)return json({error:'Armazenamento de vídeos não está configurado.'},503);
const type=(request.headers.get('Content-Type')||'').split(';')[0].trim().toLowerCase();
const allowedTypes=new Set(['video/mp4','video/webm','video/quicktime','video/3gpp','video/3gpp2','video/x-m4v']);
if(!allowedTypes.has(type))return json({error:'Formato não aceito. Escolha um vídeo MP4, MOV ou WebM.'},415);
const declaredSize=Number(request.headers.get('Content-Length')||0);
if(declaredSize>MAX_REPLACEMENT_VIDEO)return json({error:'O vídeo ultrapassa 50 MB. Reduza o tamanho e tente novamente.'},413);
const declaredDuration=Number(request.headers.get('X-Video-Duration'));
if(Number.isFinite(declaredDuration)&&declaredDuration>60)return json({error:'Cada vídeo deve ter no máximo 60 segundos.'},400);
const serviceId=String(url.searchParams.get('serviceId')||''),itemIndex=Number(url.searchParams.get('itemIndex')),part=String(url.searchParams.get('part')||'');
if(!Number.isInteger(itemIndex)||!['Válvula M30','Válvula de CO₂','Manômetro'].includes(part))return json({error:'Peça ou extintor inválido.'},400);
const state=await readState(env),service=(state.services||[]).find(x=>x.id===serviceId&&x.employeeId===session.employee_id&&!x.closed),item=service?.items?.[itemIndex];
if(!item)return json({error:'Serviço não encontrado ou não atribuído a você.'},404);
if(!(item.replacedParts||[]).includes(part))return json({error:'Registre a substituição da peça antes de enviar o vídeo.'},409);
const bytes=await request.arrayBuffer();
if(!bytes.byteLength||bytes.byteLength>MAX_REPLACEMENT_VIDEO)return json({error:'O vídeo está vazio ou ultrapassa 50 MB.'},413);
const duration=videoDurationSeconds(bytes,type);
if(!Number.isFinite(duration)||duration<=0||duration>60)return json({error:'Não foi possível validar o vídeo ou ele ultrapassa 60 segundos. Envie um MP4, MOV ou WebM de até um minuto.'},400);
const ext=type==='video/mp4'?'mp4':type==='video/quicktime'?'mov':type==='video/webm'?'webm':type==='video/x-m4v'?'m4v':type==='video/3gpp2'?'3g2':'3gp';
const key='service-media/'+randomHex(20)+'.'+ext;
await env.MEDIA.put(key,bytes,{httpMetadata:{contentType:type,cacheControl:'private,max-age=0'}});
const previous=item.replacementMedia?.[part],media={url:(env.PUBLIC_API_URL||'')+'/media/'+key,durationSeconds:Math.round(duration*10)/10,size:bytes.byteLength,contentType:type,uploadedAt:now()};
item.replacementMedia={...(item.replacementMedia||{}),[part]:media};
await saveState(env,state,(await env.DB.prepare('SELECT username FROM admin_auth WHERE id=1').first()).username);
if(previous?.url&&previous.url.startsWith((env.PUBLIC_API_URL||'')+'/media/')){
const previousKey=previous.url.slice((env.PUBLIC_API_URL||'').length+7);
if(previousKey.startsWith('service-media/'))await env.MEDIA.delete(previousKey).catch(()=>{});
}
return json({ok:true,media});
}

